  SH.snow = (x, s) => { x.lineWidth = Math.max(1, s / 7); x.beginPath(); for (let i = 0; i < 6; i++) { const a = i * 1.047; const ex = Math.cos(a) * s, ey = Math.sin(a) * s; x.moveTo(0, 0); x.lineTo(ex, ey); const bx = ex * 0.6, by = ey * 0.6; x.moveTo(bx, by); x.lineTo(bx + Math.cos(a + 0.8) * s * 0.3, by + Math.sin(a + 0.8) * s * 0.3); x.moveTo(bx, by); x.lineTo(bx + Math.cos(a - 0.8) * s * 0.3, by + Math.sin(a - 0.8) * s * 0.3); } x.stroke(); };
