  V.X.cracks = { ground: true, draw(x, cam, f, k) { const [sx, sy] = cam.w2s(f.x, f.y); const T = TS(); const grow = Math.min(1, f.t * 8); x.globalAlpha = 1 - k * k; x.strokeStyle = '#120e18'; x.lineWidth = 3; for (const pts of f.lines) { x.beginPath(); const n = Math.max(2, Math.ceil(pts.length * grow)); for (let i = 0; i < n; i++) { const [a, b] = pts[i]; i ? x.lineTo(sx + a * T, sy + b * T) : x.moveTo(sx + a * T, sy + b * T); } x.stroke(); } x.globalCompositeOperation = 'lighter'; x.strokeStyle = f.c; x.lineWidth = 1; for (const pts of f.lines) { x.beginPath(); const n = Math.max(2, Math.ceil(pts.length * grow)); for (let i = 0; i < n; i++) { const [a, b] = pts[i]; i ? x.lineTo(sx + a * T, sy + b * T) : x.moveTo(sx + a * T, sy + b * T); } x.stroke(); } x.globalCompositeOperation = 'source-over'; } };
  V.X.columns = { draw(x, cam, f, k) { const T = TS(); for (let i = 0; i < f.n; i++) { const a = f.rot + i / f.n * 6.28; const [sx, sy] = cam.w2s(f.x + Math.cos(a) * f.r, f.y + Math.sin(a) * f.r); const h = f.h * Math.sin(Math.min(1, k * 2.5) * Math.PI / 2) * (1 - k * 0.3); const g = x.createLinearGradient(0, sy - h, 0, sy); g.addColorStop(0, 'rgba(0,0,0,0)'); g.addColorStop(0.3, f.pal[1]); g.addColorStop(1, f.pal[0]); x.globalAlpha = 1 - k; x.fillStyle = g; x.fillRect(sx - f.w / 2, sy - h, f.w, h); x.fillStyle = f.pal[0]; x.fillRect(sx - 1, sy - h * 0.9, 2, h * 0.9); } } };
  V.X.orbit = { draw(x, cam, f, k) { const a0 = f.a; const ax = a0.x ?? a0, ay = a0.y; if (a0.dead) { f.t = f.dur; return; } const [sx, sy] = cam.w2s(ax, ay); x.globalAlpha = fadeIn(f, k); for (let i = 0; i < f.n; i++) { const a = f.t * f.speed + i / f.n * 6.28; const px = sx + Math.cos(a) * f.r * T_(), py = sy - f.z + Math.sin(a) * f.r * T_() * 0.55; x.save(); x.translate(px, py); x.rotate(a + Math.PI / 2); drawShape(x, f.kind, f.size, f.c, f.c2, f.t); x.restore(); x.globalCompositeOperation = 'lighter'; } } };
  const T_ = () => G.TS;
  V.X.fly = { draw(x, cam, f, k) { const px = U.lerp(f.x1, f.x2, k), py = U.lerp(f.y1, f.y2, k); const [sx, sy] = cam.w2s(px, py); const ang = Math.atan2(f.y2 - f.y1, f.x2 - f.x1); x.save(); x.translate(sx, sy - f.z - Math.sin(k * Math.PI) * f.arc); x.rotate(f.spin ? f.t * f.spin : ang); x.globalAlpha = 1; drawShape(x, f.kind, f.size, f.c, null, f.t); x.restore(); x.globalCompositeOperation = 'lighter'; } };
