  V.X.links = { draw(x, cam, f, k) { const prog = Math.min(1, f.t * 5); x.globalAlpha = 1 - k * k; x.strokeStyle = f.c; x.lineWidth = 1.5; x.beginPath(); const n = f.pts.length; const upto = prog * (n - 1); for (let i = 0; i < n; i++) { if (i > upto + 1) break; let [a, b] = f.pts[i]; if (i > upto) { const [pa, pb] = f.pts[i - 1]; const q = upto - (i - 1); a = U.lerp(pa, a, q); b = U.lerp(pb, b, q); } const [sx, sy] = cam.w2s(a, b); i ? x.lineTo(sx, sy - f.z) : x.moveTo(sx, sy - f.z); } x.stroke(); x.fillStyle = '#ffffff'; for (let i = 0; i <= Math.min(n - 1, upto); i++) { const [sx, sy] = cam.w2s(f.pts[i][0], f.pts[i][1]); x.save(); x.translate(sx, sy - f.z); x.rotate(f.t * 2); SH.star4(x, 4 + Math.sin(f.t * 12 + i) * 1.5); x.restore(); } } };
